from numpy import *

from random import randint

T = array([str] * 12)


def Remplir():
    for i in range(12):
        b = False
        while not b:
            T[i] = input("T[" + str(i) + "]=")
            b = verif(T[i])


def verif(ch):
    ok = len(ch) > 3
    i = -1
    while ok and i < len(ch) - 1:
        i += 1
        ok = "A" <= ch[i] <= "Z"
    return ok


def Trier(T):
    p = randint(1, 3)
    n = 12

    echange = False
    while n != 1 or not (echange):
        for i in range(11):
            if T[i][p] > T[i + 1][p]:
                temp = T[i]
                T[i] = T[i + 1]
                T[i + 1] = temp
                echange = True
        n -= 1


def Afficher(T):
    for i in range(0, 12, 3):
        print(T[i], T[i + 1], T[i + 2], end="\n")


Remplir()
Trier(T)
Afficher(T)

